// Prépare un brouillon de réponse selon la note. Rien n'est publié automatiquement.
const avis = $('Nouvel avis reçu').all();
return avis.map((item) => {
  const a = item.json.body ?? item.json;
  const note = Number(a.rating);
  const auteur = String(a.author ?? '').trim();
  const salutation = auteur ? `Bonjour ${auteur},` : 'Bonjour,';
  let brouillon;
  if (note < 3) {
    brouillon = `${salutation}\n\nMerci d'avoir pris le temps de partager votre expérience. Nous sommes désolés qu'elle n'ait pas été à la hauteur. Pouvez-vous nous contacter directement pour que nous comprenions ce qui s'est passé ?`;
  } else if (note >= 4) {
    brouillon = `${salutation}\n\nMerci beaucoup pour votre avis, cela fait plaisir à toute l'équipe. Au plaisir de vous revoir !`;
  } else {
    brouillon = `${salutation}\n\nMerci pour votre retour. Nous prenons note de vos remarques pour nous améliorer.`;
  }
  return {
    json: {
      reviewId: String(a.reviewId ?? ''),
      auteur,
      note: Number.isFinite(note) ? note : null,
      texte: String(a.comment ?? ''),
      date: String(a.createTime ?? new Date().toISOString()),
      urgent: note < 3,
      brouillon,
      statut: 'Brouillon à valider',
    },
  };
});
